/* CSS PART 1 OF 2 */

/* -----------------------------------------
   DESIGN TOKENS
----------------------------------------- */
:root {
  color-scheme: light;
  --forest: #203e30;
  --forest-deep: #172d24;
  --sage: #87977b;
  --sage-light: #e8ede3;
  --sun: #dcae58;
  --clay: #bd7959;
  --cream: #f7f5ed;
  --paper: #fffefa;
  --ink: #28352c;
  --muted: #72786d;
  --line: #e1e2d8;

  --font-display: "DM Serif Display", Georgia, serif;
  --font-body: "DM Sans", Arial, sans-serif;

  --container: 1200px;
  --gutter: clamp(24px, 6vw, 88px);
  --section-space: clamp(76px, 10vw, 132px);

  --radius-sm: 5px;
  --radius-md: 12px;
  --radius-lg: 22px;

  --shadow-soft: 0 14px 45px rgba(32, 62, 48, 0.09);
  --transition: 220ms ease;
}

/* -----------------------------------------
   RESET & BASE
----------------------------------------- */
* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 100px;
}

body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input,
textarea,
select {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

::selection {
  background: var(--sage);
  color: white;
}

:focus-visible {
  outline: 3px solid var(--sun);
  outline-offset: 5px;
}

h1,
h2,
h3,
p {
  margin-top: 0;
}

h1,
h2,
h3 {
  font-family: var(--font-display);
  font-weight: 400;
  line-height: 1.12;
  letter-spacing: -0.025em;
}

h1 {
  font-size: clamp(3.2rem, 7.2vw, 6.8rem);
}

h2 {
  font-size: clamp(2.5rem, 4.5vw, 4.3rem);
}

h3 {
  font-size: clamp(1.55rem, 2.2vw, 2rem);
}

p {
  color: var(--muted);
}

.container {
  width: min(var(--container), calc(100% - var(--gutter) * 2));
  margin-inline: auto;
}

.section {
  padding-block: var(--section-space);
}

.section--cream {
  background: var(--cream);
}

.section--green {
  background: var(--forest);
  color: white;
}

.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 22px;
  color: var(--clay);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.19em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow::before {
  width: 30px;
  height: 1px;
  background: currentColor;
  content: "";
}

.section-heading {
  max-width: 720px;
  margin-bottom: 54px;
}

.section-heading h2 {
  margin-bottom: 20px;
}

.section-heading p {
  max-width: 570px;
  margin-bottom: 0;
  font-size: 1.05rem;
}

/* -----------------------------------------
   HEADER & NAVIGATION
----------------------------------------- */
.site-header {
  position: relative;
  z-index: 20;
  width: 100%;
  background: var(--paper);
  border-bottom: 1px solid rgba(32, 62, 48, 0.08);
}

.header-inner {
  display: flex;
  min-height: 88px;
  align-items: center;
  justify-content: space-between;
  gap: 32px;
}

.brand {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  gap: 13px;
}

.brand__logo {
  width: auto;
  max-width: 190px;
  max-height: 62px;
  object-fit: contain;
}

.brand__text {
  display: flex;
  flex-direction: column;
  color: var(--forest);
  font-family: var(--font-display);
  font-size: 1.35rem;
  line-height: 1.05;
}

.brand__text span {
  margin-top: 6px;
  color: var(--muted);
  font-family: var(--font-body);
  font-size: 0.59rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.site-nav {
  display: flex;
  align-items: center;
  gap: clamp(20px, 3vw, 40px);
}

.site-nav a:not(.button) {
  position: relative;
  padding-block: 12px;
  color: var(--forest);
  font-size: 0.86rem;
  font-weight: 600;
  transition: color var(--transition);
}

.site-nav a:not(.button)::after {
  position: absolute;
  right: 0;
  bottom: 4px;
  left: 0;
  height: 1px;
  background: var(--clay);
  content: "";
  transform: scaleX(0);
  transform-origin: left;
  transition: transform var(--transition);
}

.site-nav a:not(.button):hover {
  color: var(--clay);
}

.site-nav a:not(.button):hover::after {
  transform: scaleX(1);
}

.header-cta {
  flex-shrink: 0;
}

/* -----------------------------------------
   BUTTONS
----------------------------------------- */
.button {
  display: inline-flex;
  min-height: 54px;
  align-items: center;
  justify-content: center;
  gap: 13px;
  padding: 14px 25px;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  cursor: pointer;
  font-size: 0.82rem;
  font-weight: 700;
  letter-spacing: 0.025em;
  text-align: center;
  transition:
    background var(--transition),
    color var(--transition),
    border-color var(--transition),
    transform var(--transition);
}

.button:hover {
  transform: translateY(-2px);
}

.button__arrow {
  font-size: 1.1rem;
  line-height: 1;
  transition: transform var(--transition);
}

.button:hover .button__arrow {
  transform: translateX(4px);
}

.button--primary {
  background: var(--forest);
  color: white;
}

.button--primary:hover {
  background: var(--forest-deep);
}

.button--light {
  background: var(--cream);
  color: var(--forest);
}

.button--light:hover {
  background: white;
}

.button--outline {
  border-color: rgba(255, 255, 255, 0.75);
  background: transparent;
  color: white;
}

.button--outline:hover {
  background: white;
  color: var(--forest);
}

.button--outline-dark {
  border-color: var(--forest);
  background: transparent;
  color: var(--forest);
}

.button--outline-dark:hover {
  background: var(--forest);
  color: white;
}

/* -----------------------------------------
   FULL-BLEED HERO
----------------------------------------- */
.hero {
  position: relative;
  display: flex;
  min-height: min(760px, 82vh);
  min-height: min(760px, 82svh);
  align-items: center;
  overflow: hidden;
  background: var(--forest-deep);
  color: white;
}

.hero__media {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.hero__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 54%;
}

.hero__overlay {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      90deg,
      rgba(18, 39, 29, 0.88) 0%,
      rgba(18, 39, 29, 0.68) 43%,
      rgba(18, 39, 29, 0.12) 100%
    ),
    linear-gradient(
      0deg,
      rgba(18, 39, 29, 0.25),
      transparent 45%
    );
}

.hero__inner {
  position: relative;
  z-index: 1;
  width: 100%;
  padding-block: clamp(100px, 14vw, 175px);
}

.hero__content {
  max-width: 760px;
}

.hero .eyebrow {
  color: #e8c47d;
}

.hero h1 {
  max-width: 780px;
  margin-bottom: 25px;
  color: white;
}

.hero h1 em {
  color: #e7c47e;
  font-weight: 400;
}

.hero__description {
  max-width: 540px;
  margin-bottom: 35px;
  color: rgba(255, 255, 255, 0.87);
  font-size: clamp(1rem, 1.5vw, 1.15rem);
  line-height: 1.8;
}

.hero__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 14px;
}

.hero__note {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 32px;
  color: rgba(255, 255, 255, 0.85);
  font-size: 0.8rem;
  font-weight: 500;
}

.hero__note::before {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--sun);
  content: "";
}

/* -----------------------------------------
   INTRODUCTION / BRAND PROMISE
----------------------------------------- */
.intro {
  position: relative;
  overflow: hidden;
  background: var(--cream);
}

.intro__inner {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  align-items: center;
  gap: clamp(45px, 9vw, 125px);
}

.intro__aside {
  position: relative;
  padding: 38px 0 38px 34px;
  border-left: 2px solid var(--sun);
}

.intro__aside p {
  margin-bottom: 0;
  color: var(--forest);
  font-family: var(--font-display);
  font-size: clamp(1.65rem, 2.7vw, 2.5rem);
  line-height: 1.3;
}

.intro__content h2 {
  margin-bottom: 24px;
  color: var(--forest);
}

.intro__content > p {
  max-width: 590px;
  margin-bottom: 28px;
  font-size: 1.02rem;
}

.intro__highlights {
  display: flex;
  flex-wrap: wrap;
  gap: 12px 28px;
  margin-top: 28px;
}

.intro__highlight {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: var(--forest);
  font-size: 0.83rem;
  font-weight: 700;
}

.intro__highlight::before {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--clay);
  content: "";
}

/* -----------------------------------------
   SERVICES
----------------------------------------- */
.services {
  background: var(--paper);
}

.services__layout {
  display: grid;
  grid-template-columns: 0.78fr 1.22fr;
  align-items: start;
  gap: clamp(45px, 8vw, 110px);
}

.services__intro {
  position: sticky;
  top: 35px;
}

.services__intro h2 {
  margin-bottom: 24px;
  color: var(--forest);
}

.services__intro > p {
  max-width: 400px;
  margin-bottom: 30px;
}

.services__list {
  border-top: 1px solid var(--line);
}

.service-item {
  display: grid;
  grid-template-columns: 54px 1fr auto;
  align-items: center;
  gap: 20px;
  padding: 27px 0;
  border-bottom: 1px solid var(--line);
  transition: padding var(--transition);
}

.service-item:hover {
  padding-inline: 10px;
}

.service-item__number {
  color: var(--clay);
  font-family: var(--font-display);
  font-size: 1.35rem;
}

.service-item__content h3 {
  margin-bottom: 7px;
  color: var(--forest);
  font-size: clamp(1.45rem, 2.3vw, 1.9rem);
}

.service-item__content p {
  max-width: 470px;
  margin-bottom: 0;
  font-size: 0.9rem;
  line-height: 1.65;
}

.service-item__arrow {
  display: grid;
  width: 40px;
  height: 40px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  color: var(--forest);
  font-size: 1.2rem;
  transition: all var(--transition);
}

.service-item:hover .service-item__arrow {
  border-color: var(--forest);
  background: var(--forest);
  color: white;
}

/* -----------------------------------------
   MATERIALS & CRAFT
----------------------------------------- */
.materials {
  overflow: hidden;
  background: var(--forest);
  color: white;
}

.materials__inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: clamp(45px, 8vw, 105px);
}

.materials__content h2 {
  max-width: 550px;
  margin-bottom: 24px;
  color: white;
}

.materials__content > p {
  max-width: 500px;
  margin-bottom: 30px;
  color: rgba(255, 255, 255, 0.76);
}

.materials__details {
  display: flex;
  flex-direction: column;
  gap: 18px;
  margin-top: 35px;
}

.materials__detail {
  display: flex;
  align-items: flex-start;
  gap: 15px;
  color: rgba(255, 255, 255, 0.9);
  font-size: 0.9rem;
}

.materials__detail::before {
  width: 9px;
  height: 9px;
  flex: 0 0 9px;
  margin-top: 8px;
  border-radius: 50%;
  background: var(--sun);
  content: "";
}

.materials__image {
  position: relative;
  min-height: 440px;
  overflow: hidden;
  border-radius: var(--radius-lg);
}

.materials__image img {
  width: 100%;
  height: 100%;
  min-height: 440px;
  object-fit: cover;
  object-position: center;
}

.materials__caption {
  position: absolute;
  right: 20px;
  bottom: 20px;
  left: 20px;
  padding: 16px 20px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: var(--radius-sm);
  background: rgba(23, 45, 36, 0.82);
  color: white;
  font-size: 0.83rem;
  backdrop-filter: blur(8px);
}

/* -----------------------------------------
   IMAGE / PROJECT SHOWCASE
----------------------------------------- */
.showcase {
  background: var(--cream);
}

.showcase__heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 35px;
  margin-bottom: 45px;
}

.showcase__heading .section-heading {
  margin-bottom: 0;
}

.showcase__heading h2 {
  color: var(--forest);
}

.showcase__visual {
  position: relative;
  min-height: 430px;
  overflow: hidden;
  border-radius: var(--radius-lg);
  background: var(--sage-light);
}

.showcase__visual img {
  width: 100%;
  height: 100%;
  min-height: 430px;
  object-fit: cover;
}

.showcase__label {
  position: absolute;
  right: 25px;
  bottom: 25px;
  left: 25px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 22px 26px;
  border-radius: var(--radius-md);
  background: var(--paper);
  box-shadow: var(--shadow-soft);
}

.showcase__label h3 {
  margin-bottom: 4px;
  color: var(--forest);
  font-size: 1.55rem;
}

.showcase__label p {
  margin-bottom: 0;
  font-size: 0.84rem;
}

/* -----------------------------------------
   PROMOTIONAL FEATURE
----------------------------------------- */
.promotion {
  position: relative;
  overflow: hidden;
  padding-block: clamp(65px, 9vw, 105px);
  background: var(--sage-light);
}

.promotion__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 45px;
}

.promotion__content {
  max-width: 720px;
}

.promotion__content h2 {
  margin-bottom: 16px;
  color: var(--forest);
}

.promotion__content p {
  max-width: 580px;
  margin-bottom: 0;
}

.promotion__action {
  flex-shrink: 0;
}

/* -----------------------------------------
   SHARED DECORATIVE DETAILS
----------------------------------------- */
.section-divider {
  width: 48px;
  height: 2px;
  margin-block: 25px;
  background: var(--sun);
}

.text-link {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  color: var(--forest);
  font-size: 0.85rem;
  font-weight: 700;
  transition: gap var(--transition);
}

.text-link:hover {
  gap: 16px;
}

.text-link span {
  color: var(--clay);
  font-size: 1.15rem;
}
