/* CSS PART 2 OF 2 */

/* -----------------------------------------
   CONTACT / CONVERSION
----------------------------------------- */
.contact {
  padding-block: var(--section-space);
  background: var(--cream);
}

.contact__inner {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  gap: clamp(45px, 8vw, 110px);
  align-items: start;
}

.contact__content h2 {
  margin-bottom: 22px;
  color: var(--forest);
}

.contact__content > p {
  max-width: 440px;
  margin-bottom: 30px;
}

.contact__details {
  display: flex;
  flex-direction: column;
  gap: 15px;
  margin-top: 35px;
}

.contact__detail {
  color: var(--forest);
  font-size: 0.9rem;
  font-weight: 600;
}

.contact__form {
  padding: clamp(25px, 4vw, 48px);
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  background: var(--paper);
  box-shadow: var(--shadow-soft);
}

.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 22px;
}

.form-field {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: 8px;
}

.form-field--full {
  grid-column: 1 / -1;
}

.form-field label {
  color: var(--forest);
  font-size: 0.82rem;
  font-weight: 700;
}

.form-field input,
.form-field select,
.form-field textarea {
  width: 100%;
  min-height: 52px;
  padding: 13px 15px;
  border: 1px solid #d8dbd1;
  border-radius: var(--radius-sm);
  background: white;
  color: var(--ink);
  font-size: 0.94rem;
  transition: border-color var(--transition), box-shadow var(--transition);
}

.form-field textarea {
  min-height: 145px;
  resize: vertical;
}

.form-field input::placeholder,
.form-field textarea::placeholder {
  color: #858a80;
}

.form-field input:focus,
.form-field select:focus,
.form-field textarea:focus {
  border-color: var(--forest);
  outline: none;
  box-shadow: 0 0 0 3px rgba(32, 62, 48, 0.12);
}

.contact__form .button {
  width: 100%;
  margin-top: 25px;
}

.form-note {
  margin: 14px 0 0;
  color: var(--muted);
  font-size: 0.76rem;
  text-align: center;
}

/* -----------------------------------------
   FOOTER
----------------------------------------- */
.site-footer {
  padding-top: 65px;
  background: var(--forest-deep);
  color: white;
}

.footer__main {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 55px;
  padding-bottom: 55px;
}

.footer__brand {
  max-width: 390px;
}

.footer__brand .brand__text {
  color: white;
}

.footer__brand .brand__text span {
  color: rgba(255, 255, 255, 0.65);
}

.footer__brand p {
  max-width: 350px;
  margin-top: 24px;
  margin-bottom: 0;
  color: rgba(255, 255, 255, 0.7);
  font-size: 0.9rem;
}

.footer__links {
  display: flex;
  flex-wrap: wrap;
  gap: 18px 32px;
  padding-top: 8px;
}

.footer__links a {
  color: rgba(255, 255, 255, 0.83);
  font-size: 0.85rem;
  transition: color var(--transition);
}

.footer__links a:hover {
  color: var(--sun);
}

.footer__bottom {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  padding-block: 22px;
  border-top: 1px solid rgba(255, 255, 255, 0.16);
  color: rgba(255, 255, 255, 0.6);
  font-size: 0.76rem;
}

/* -----------------------------------------
   ACCESSIBLE MOBILE MENU CONTROL
----------------------------------------- */
.menu-toggle {
  display: none;
  width: 46px;
  height: 46px;
  flex: 0 0 46px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border: 1px solid var(--line);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--forest);
  cursor: pointer;
}

.menu-toggle span[aria-hidden="true"] {
  display: block;
  width: 20px;
  height: 2px;
  flex: 0 0 2px;
  background-color: currentColor;
}

/* -----------------------------------------
   RESPONSIVE: LARGE TABLETS
----------------------------------------- */
@media (max-width: 1000px) {
  :root {
    --gutter: clamp(24px, 5vw, 55px);
    --section-space: 85px;
  }

  .site-nav {
    gap: 17px;
  }

  .site-nav a:not(.button) {
    font-size: 0.79rem;
  }

  .brand__logo {
    max-width: 155px;
  }

  .intro__inner,
  .services__layout,
  .materials__inner,
  .contact__inner {
    gap: 45px;
  }

  .materials__image,
  .materials__image img {
    min-height: 370px;
  }
}

/* -----------------------------------------
   RESPONSIVE: TABLETS & MOBILE NAVIGATION
----------------------------------------- */
@media (max-width: 760px) {
  :root {
    --gutter: 24px;
    --section-space: 72px;
  }

  html {
    scroll-padding-top: 75px;
  }

  .header-inner {
    min-height: 74px;
    gap: 12px;
  }

  .brand__logo {
    max-width: 145px;
    max-height: 53px;
  }

  .menu-toggle {
    display: flex;
  }

  .site-nav {
    display: none;
    position: absolute;
    top: 100%;
    right: 0;
    left: 0;
    max-height: calc(100svh - 74px);
    overflow-y: auto;
    flex-direction: column;
    align-items: stretch;
    gap: 0;
    padding: 12px var(--gutter) 24px;
    border-top: 1px solid var(--line);
    border-bottom: 1px solid var(--line);
    background: var(--paper);
    box-shadow: var(--shadow-soft);
  }

  .site-nav.is-open {
    display: flex;
  }

  .site-nav a:not(.button) {
    display: block;
    width: 100%;
    padding: 14px 4px;
    border-bottom: 1px solid var(--line);
    font-size: 0.95rem;
  }

  .site-nav a:not(.button)::after {
    display: none;
  }

  .site-nav .button {
    width: 100%;
    margin-top: 15px;
  }

  .header-cta {
    display: none;
  }

  .hero {
    min-height: 690px;
    min-height: min(740px, 88svh);
  }

  .hero__media img {
    object-position: 60% center;
  }

  .hero__overlay {
    background: linear-gradient(
      90deg,
      rgba(18, 39, 29, 0.84),
      rgba(18, 39, 29, 0.54)
    );
  }

  .hero__inner {
    padding-block: 100px;
  }

  .hero h1 {
    font-size: clamp(3.1rem, 11vw, 5.2rem);
  }

  .intro__inner,
  .services__layout,
  .materials__inner,
  .contact__inner {
    grid-template-columns: 1fr;
  }

  .intro__inner {
    gap: 35px;
  }

  .intro__aside {
    max-width: 570px;
    padding-block: 15px;
  }

  .services__intro {
    position: static;
  }

  .services__list {
    width: 100%;
  }

  .materials__inner {
    gap: 35px;
  }

  .materials__image,
  .materials__image img {
    min-height: 330px;
  }

  .showcase__heading {
    align-items: flex-start;
    flex-direction: column;
    gap: 20px;
  }

  .showcase__visual,
  .showcase__visual img {
    min-height: 340px;
  }

  .promotion__inner {
    align-items: flex-start;
    flex-direction: column;
    gap: 28px;
  }

  .contact__inner {
    gap: 35px;
  }

  .footer__main {
    flex-direction: column;
    gap: 35px;
  }

  .footer__bottom {
    flex-direction: column;
    gap: 8px;
  }
}

/* -----------------------------------------
   RESPONSIVE: SMALL MOBILE
----------------------------------------- */
@media (max-width: 480px) {
  :root {
    --gutter: 19px;
    --section-space: 62px;
  }

  body {
    font-size: 15px;
  }

  .brand__logo {
    max-width: 125px;
  }

  .hero {
    min-height: 650px;
    min-height: 86svh;
  }

  .hero__inner {
    padding-block: 85px;
  }

  .hero h1 {
    font-size: clamp(2.85rem, 12vw, 4rem);
  }

  .hero__description {
    font-size: 0.96rem;
  }

  .hero__actions {
    align-items: stretch;
    flex-direction: column;
  }

  .hero__actions .button {
    width: 100%;
  }

  .hero__note {
    align-items: flex-start;
  }

  .section-heading {
    margin-bottom: 35px;
  }

  .intro__aside {
    padding-left: 22px;
  }

  .service-item {
    grid-template-columns: 35px minmax(0, 1fr) 30px;
    gap: 10px;
    padding-block: 22px;
  }

  .service-item:hover {
    padding-inline: 0;
  }

  .service-item__content h3 {
    font-size: 1.4rem;
  }

  .service-item__content p {
    font-size: 0.84rem;
  }

  .service-item__arrow {
    width: 30px;
    height: 30px;
  }

  .materials__image,
  .materials__image img {
    min-height: 270px;
  }

  .showcase__visual,
  .showcase__visual img {
    min-height: 290px;
  }

  .showcase__label {
    right: 12px;
    bottom: 12px;
    left: 12px;
    padding: 15px;
  }

  .showcase__label h3 {
    font-size: 1.25rem;
  }

  .form-grid {
    grid-template-columns: 1fr;
    gap: 17px;
  }

  .form-field--full {
    grid-column: auto;
  }

  .contact__form {
    padding: 22px 17px;
  }

  .footer__links {
    flex-direction: column;
    gap: 13px;
  }
}

/* -----------------------------------------
   KEYBOARD FOCUS & MOTION PREFERENCES
----------------------------------------- */
:where(a, button, input, select, textarea, [tabindex]):focus-visible {
  outline: 3px solid var(--sun);
  outline-offset: 4px;
}

.menu-toggle:focus-visible,
.button:focus-visible {
  outline-color: var(--clay);
  outline-offset: 4px;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}
